    descriptionAdvanced: {
      de: "Der Burana-Turm ist ein bedeutendes archäologisches Denkmal im Tschüi-Tal im Norden Kirgisistans und stellt eines der ältesten erhaltenen Bauwerke Zentralasiens dar. Er wurde im 11. Jahrhundert von den Karachaniden erbaut und diente ursprünglich als Minarett für eine prachtvolle Moschee in der antiken Stadt Balasagun. In seiner Blütezeit erreichte der Turm eine beeindruckende Höhe von etwa 45 Metern, doch schwere Erdbeben im 15. und 16. Jahrhundert führten dazu, dass der obere Teil einstürzte. Heute misst das Bauwerk noch rund 25 Meter und ist über eine steile Wendeltreppe im Inneren für Besucher zugänglich. Das umliegende Areal beherbergt eine faszinierende Sammlung von Balbals, anthropomorphen Grabstelen aus dem 6. bis 10. Jahrhundert, die von nomadischen Turkvölkern stammen. Seit 2014 gehört die gesamte Ausgrabungsstätte zum UNESCO-Weltkulturerbe als Teil des Netzwerks der Seidenstraße. Die kunstvollen Ziegelmuster an der Fassade zeugen von der hohen handwerklichen Kunstfertigkeit der mittelalterlichen Baumeister dieser Region.",
      hu: "A Burana-torony Kirgizisztán északi részén, a Csuj-völgyben található jelentős régészeti emlék, amely Közép-Ázsia egyik legrégebbi fennmaradt építménye. A 11. században építették a Karahanidák idején, és eredetileg az ősi Balaszagun város nagymecsetének minaretjeként szolgált. Virágkorában a torony magassága elérte a 45 métert, azonban a 15. és 16. századi súlyos földrengések következtében a felső része leomlott, így ma már csak mintegy 25 méter magas. A látogatók egy meredek, belső csigalépcsőn keresztül juthatnak fel a tetejére, ahonnan pazar kilátás nyílik a Tien-san hegység vonulataira. A torony körüli területen egy szabadtéri múzeum található, ahol a 6-10. századból származó balbalokat, azaz faragott sírköveket őriznek. 2014 óta a helyszín az UNESCO Világörökség része, mint a Selyemút egyik fontos állomása. A homlokzaton látható geometrikus tégla díszítések a középkori építészet és mérnöki tudás kiváló példái.",
      ro: "Turnul Burana este un monument arheologic de primă importanță situat în Valea Chuy din nordul Kârgâzstanului, fiind una dintre cele mai vechi structuri medievale păstrate în Asia Centrală. Construit în secolul al XI-lea de către dinastia Karahanidă, acesta a servit inițial ca minaret pentru o moschee impunătoare în orașul antic Balasagun. În perioada sa de glorie, turnul atingea o înălțime de aproximativ 45 de metri, însă cutremurele devastatoare din secolele XV și XVI au cauzat prăbușirea secțiunii superioare. Astăzi, structura măsoară circa 25 de metri și poate fi vizitată urcând pe o scară interioară îngustă și abruptă. Complexul include un muzeu în aer liber ce adăpostește o colecție impresionantă de balbal-uri, stele funerare antropomorfe datând din secolele VI-X. În anul 2014, situl a fost inclus în Patrimoniul Mondial UNESCO ca parte a coridorului Chang'an-Tianshan de pe Drumul Mătăsii. Ornamentația exterioară din cărămidă reflectă rafinamentul artistic al arhitecturii islamice timpurii din regiune.",
      en: "The Burana Tower is a significant archaeological landmark situated in the Chuy Valley of northern Kyrgyzstan, representing one of the oldest surviving structures in Central Asia. Built in the 11th century by the Karakhanid dynasty, it originally served as a minaret for a grand mosque in the ancient city of Balasagun, a key stop on the Silk Road. In its original form, the tower reached a height of approximately 45 meters, but severe earthquakes in the 15th and 16th centuries caused the upper portion to collapse, leaving the tower at its current height of 25 meters. Visitors can climb to the top via a steep internal spiral staircase to enjoy panoramic views of the surrounding valley and the Tian Shan mountains. The site also features an open-air museum displaying a vast collection of balbals, or anthropomorphic stone grave markers, dating from the 6th to the 10th centuries. In 2014, the complex was designated as a UNESCO World Heritage site, highlighting its role as a cultural crossroads during the medieval era.",
      es: "La Torre de Burana es un gran minarete situado en el valle de Chuy, en el norte de Kirguistán. Fue construida en el siglo XI y es uno de los pocos restos que quedan de la antigua ciudad de Balasagun, fundada por los Qarajánidas. Originalmente la torre medía 45 metros de altura, pero tras varios terremotos, especialmente en el siglo XV, su altura se redujo a los 25 metros actuales. El sitio también incluye un campo de estatuas de piedra de guerreros llamadas Balbals, así como un pequeño museo que exhibe hallazgos arqueológicos de los alrededores. La torre da testimonio de la importancia de la región a lo largo de la Gran Ruta de la Seda y hoy es un monumento histórico protegido.",
      pt: "A Torre de Burana é um grande minarete no vale de Chuy, no norte do Quirguistão. Foi construída no século XI e é um dos poucos vestígios restantes da antiga cidade de Balasagun, fundada pelos Caracânidas. Originalmente, a torre tinha 45 metros de altura, mas após vários terramotos, especialmente no século XV, foi reduzida para a sua altura atual de 25 metros. O local inclui também um campo de estátuas de pedra de guerreiros, chamadas Balbals, bem como um pequeno museu onde estão expostos achados arqueológicos da área circundante. A torre testemunha a importância da região ao longo da Rota da Seda e é hoje um monumento histórico protegido.",
      fr: "La tour Bourana est un grand minaret situé dans la vallée de Tchouï, au nord du Kirghizistan. Construite au XIe siècle, elle est l'un des rares vestiges de l'ancienne cité de Balasagun, fondée par les Karakhanides. À l'origine, la tour mesurait 45 mètres de haut, mais après plusieurs séismes, notamment au XVe siècle, sa hauteur a été ramenée à 25 mètres. Le site comprend également un champ de statues de guerriers en pierre appelées Balbals, ainsi qu'un petit musée exposant des découvertes archéologiques des environs. La tour témoigne de l'importance de la région le long de la Route de la Soie et est aujourd'hui un monument historique protégé.",
    },
