      hu: ["2002-ben alapították az Iszik-köl tó partján.", "5 teljesen egyforma kápolna jelképezi a világvallásokat.", "Csingiz Ajtmatov kirgiz író nevét viseli a központ.", "Több mint 100 szobor található a szabadtéri múzeumban.", "Saját koncertteremmel és úszó színpaddal rendelkezik.", "Nemzetközi diplomáciai csúcstalálkozók rendszeres helyszíne."],
      ro: ["Fondat în anul 2002 pe malul lacului Issyk-Kul.", "Include 5 capele identice dedicate religiilor lumii.", "Poartă numele scriitorului kârgâz Chingiz Aitmatov.", "Găzduiește peste 100 de sculpturi într-un muzeu în aer liber.", "Dispune de o sală de concerte cu o scenă plutitoare.", "Funcționează ca loc de întâlnire pentru summituri internaționale."],
      en: ["Founded in 2002 on the northern shore of Issyk-Kul.", "Features 5 identical chapels representing global religions.", "Named in honor of the Kyrgyz writer Chingiz Aitmatov.", "The open-air museum contains over 100 historical statues.", "Includes a concert hall with a unique floating stage.", "Serves as a frequent venue for international diplomatic summits."],
      es: ["Se encuentra en Cholpon-Ata, en la orilla norte del lago Issyk-Kul.", "El nombre significa 'Centro Espiritual' en lengua kirguisa.", "Cuenta con cinco capillas que representan las grandes religiones del mundo.", "Alberga exposiciones dedicadas al escritor Chingiz Aitmatov.", "Fundado en 2002 como un espacio para el diálogo intercultural.", "El recinto está decorado con numerosas esculturas de bronce y piedra."],
      pt: ["Localiza-se em Cholpon-Ata, na margem norte do lago Issyk-Kul.", "O nome significa 'Centro Espiritual' na língua quirguiz.", "Possui cinco capelas que representam as grandes religiões do mundo.", "Acolhe exposições dedicadas ao escritor Chingiz Aitmatov.", "Fundado em 2002 como um local de tolerância e cultura.", "O terreno está decorado com numerosas esculturas de bronze e pedra."],
      fr: ["Situé à Cholpon-Ata sur la rive nord du lac Issyk-Koul.", "Le nom signifie 'Centre Spirituel' en langue kirghize.", "Dispose de cinq chapelles représentant les grandes religions du monde.", "Abrite des expositions dédiées à l'écrivain Tchinguiz Aïtmatov.", "Fondé en 2002 comme lieu de tolérance et de culture.", "Le site est orné de nombreuses sculptures en bronze et en pierre."],
